import sys
import math
import random

def is_prime(k: int) -> bool:
    if k == 1:
        return False
    if k == 2 or k == 3:
        return True
    limit = int(math.sqrt(k))
    for i in range(2, limit + 1):
        if k % i == 0:
            return False
    return True

def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    x = int(next(it))
    n = int(next(it))

    primes = []

    limit = int(math.sqrt(x))
    for i in range(2, limit + 1):
        if x % i == 0:
            if is_prime(i) and (x // i) not in primes:
                primes.append(i)
            if is_prime(x // i) and (x // i) not in primes:
                primes.append(x // i)
    if is_prime(x):
        primes.append(x)

    mod = 1000000007
    ans = 1

    for p in primes:
        cur_p = p
        while n // cur_p > 0:
            ans = (ans * pow(p, n // cur_p, mod)) % mod
            # Python handles big integers automatically, no overflow check needed
            cur_p *= p

    print(ans)

class Scanner:
    def __init__(self, s: sys.stdin):
        self.data = s.read().split()
        self.index = 0

    def next(self) -> str:
        if self.index >= len(self.data):
            return ""
        val = self.data[self.index]
        self.index += 1
        return val

    def next_int(self) -> int:
        return int(self.next())

    def next_long(self) -> int:
        return int(self.next())

    def next_line(self) -> str:
        # Not strictly compatible with Kotlin's readLine behavior on tokenized input
        # but provided for interface compatibility
        return " ".join(self.data[self.index:])

    def next_double(self) -> float:
        return float(self.next())

    @staticmethod
    def sys_in() -> 'Scanner':
        return Scanner(sys.stdin)

rnd = random.Random()

def sort_int_array(arr: list) -> None:
    n = len(arr)
    for i in range(n - 1):
        random_pos = i + rnd.randint(0, n - i - 2) + 1 if n - i - 1 > 0 else i
        # XOR swap (not typical in Python, but translating logic)
        # Python tuples handle swap better, but replicating XOR swap:
        arr[i] ^= arr[random_pos]
        arr[random_pos] ^= arr[i]
        arr[i] ^= arr[random_pos]
    arr.sort()

def sort_long_array(arr: list) -> None:
    n = len(arr)
    for i in range(n - 1):
        random_pos = i + rnd.randint(0, n - i - 2) + 1 if n - i - 1 > 0 else i
        arr[i] ^= arr[random_pos]
        arr[random_pos] ^= arr[i]
        arr[i] ^= arr[random_pos]
    arr.sort()

if __name__ == "__main__":
    solve()

